operators.code:
int sum = 5 + 10;
int p = 2 ^^ 3; // Exponentiation (8)
int[] a = [1, 2];
int[] b = a ~ [3]; // Concatenation ([1, 2, 3])

conditionals.code:
int x = 10;
if (x > 5) {
    // do something
} else {
    // do something else
}

string res = (x == 10) ? "Yes" : "No";

for_loop.code:
foreach (i; 0 .. 5) {
    import std.stdio; // can import locally
    writeln(i);
}

// Traditional for loop also supported
for(int j=0; j<5; j++) {}

while_loop.code:
int i = 0;
while (i < 5) {
    i++;
}

do {
    i--;
} while (i > 0);

functions.code:
int add(int a, int b) pure {
    return a + b;
}

auto multiply(T)(T a, T b) { // Template function
    return a * b;
}

maps.code:
int[string] ages; // Associative array
ages["Alice"] = 30;
ages["Bob"] = 25;

ages.remove("Bob");

if (auto age = "Alice" in ages) {
    // *age == 30
}

error_handling.code:
import std.stdio;

try {
    throw new Exception("Something went wrong");
} catch (Exception e) {
    writeln("Caught: ", e.msg);
} finally {
    writeln("Cleanup");
}

